mapper.select:
select * from new_psychological_assessment_report ni left join new_reg ur on ni.reg_id=ur.id LEFT JOIN `yh_user_make_card` AS c ON ur.`user_code` = c.`User_Code` LEFT JOIN yh_user_admin_info AS ai ON c.doctor = ai.id
ai.user_code = #{healthManagementSpecialist}
and ni.name LIKE CONCAT('%', #{name}, '%')
LIMIT #{begin}, #{limit};

select count(*) from new_psychological_assessment_report ni left join new_reg ur on ni.reg_id=ur.id LEFT JOIN `yh_user_make_card` AS c ON ur.`user_code` = c.`User_Code` LEFT JOIN yh_user_admin_info AS ai ON c.doctor = ai.id
ai.user_code = #{healthManagementSpecialist}
and ni.name LIKE CONCAT('%', #{name}, '%')
